mapper.sql:
/* SQL ID : MsgPushDAO.rcvnSearchCondition 설 명 : 푸시 수신 검색 조건 */
AND (SC.ORG_ID = #{orgId} OR MSG.SBJCT_ID IS NULL)
AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SC.DGRS_SMSTR_CHRT = #{sbjctSmstr}
AND MSG.SBJCT_ID = #{sbjctId}
AND TO_DATE(S.SNDNG_DTTM, 'YYYYMMDDHH24MISS') >= TO_DATE(#{sndngSdttm}, 'YYYY-MM-DD')
AND TO_DATE(S.SNDNG_DTTM, 'YYYYMMDDHH24MISS') <= TO_DATE(#{sndngEdttm}, 'YYYY-MM-DD') + 1 - 1/86400
AND S.SNDNG_TTL LIKE FN_LIKE_VAL(#{searchText})
AND S.SNDNGNM LIKE FN_LIKE_VAL(#{searchText})
AND S.SNDNGR_ID LIKE FN_LIKE_VAL(#{searchText})
AND EXISTS (SELECT 1 FROM TB_LMS_USER U2 WHERE U2.USER_ID = S.SNDNGR_ID AND U2.MBL_PHN LIKE FN_LIKE_VAL(#{searchText}))
AND S.SNDNG_CTS LIKE FN_LIKE_VAL(#{searchText})

/*
     SQL ID : MsgPushDAO.sndngSearchCondition
     설  명 : 푸시 발신 검색 조건
 */

    AND (ORG.ORG_ID = #{orgId} OR MSG.SBJCT_ID IS NULL)


    AND SBJCT.SBJCT_YR = #{sbjctYr}


    AND SC.DGRS_SMSTR_CHRT = #{sbjctSmstr}


    AND MSG.SBJCT_ID = #{sbjctId}


    AND TO_DATE(NVL(SS.SNDNG_DTTM, MSG.RSRV_SNDNG_SDTTM), 'YYYYMMDDHH24MISS') >= TO_DATE(#{sndngSdttm}, 'YYYY-MM-DD')


    AND TO_DATE(NVL(SS.SNDNG_DTTM, MSG.RSRV_SNDNG_SDTTM), 'YYYYMMDDHH24MISS') <= TO_DATE(#{sndngEdttm}, 'YYYY-MM-DD') + 1 - 1/86400



        AND MSG.TTL LIKE FN_LIKE_VAL(#{searchText})




        AND EXISTS (SELECT 1 FROM TB_LMS_USER U2 WHERE U2.USER_ID = MSG.RGTR_ID AND U2.USERNM LIKE FN_LIKE_VAL(#{searchText}))




        AND MSG.RGTR_ID LIKE FN_LIKE_VAL(#{searchText})




        AND EXISTS (SELECT 1 FROM TB_LMS_USER U2 WHERE U2.USER_ID = MSG.RGTR_ID AND U2.MBL_PHN LIKE FN_LIKE_VAL(#{searchText}))




        AND EXISTS (SELECT 1 FROM TB_LMS_MSG_MBL_SNDNG S2 WHERE S2.MSG_ID = MSG.MSG_ID AND S2.MBL_SNDNG_TYCD = #{mblSndngTycd} AND S2.SNDNG_CTS LIKE FN_LIKE_VAL(#{searchText}))



    AND MSG.RGTR_ID = #{userId}

mapper.select:
/* SQL ID : MsgPushDAO.selectPushRcvnList 설 명 : 푸시 수신 목록 조회 */
SELECT S.MSG_MBL_SNDNG_ID , S.MSG_ID , S.SNDNG_TTL , S.SNDNGNM , S.SNDNG_DTTM , T.READ_DTTM , T.READ_YN , SBJCT.SBJCT_YR , SC.SMSTR_CHRTNM AS SBJCT_SMSTR , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , ORG.ORGNM , ROW_NUMBER() OVER (ORDER BY S.SNDNG_DTTM DESC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT FROM TB_LMS_MSG_MBL_SNDNG S INNER JOIN TB_LMS_MSG MSG ON S.MSG_ID = MSG.MSG_ID LEFT JOIN TB_LMS_MSG_RCV_TRGTR T ON S.MSG_ID = T.MSG_ID AND S.RCVR_ID = T.USER_ID LEFT JOIN TB_LMS_SBJCT SBJCT ON MSG.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SC ON SBJCT.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON SC.ORG_ID = ORG.ORG_ID WHERE S.RCVR_ID = #{rcvrId} AND S.MBL_SNDNG_TYCD = #{mblSndngTycd} AND S.RCVR_DELYN = 'N' AND NVL(S.SNDNG_STSCD, CASE WHEN S.SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) = 'SCS'
ORDER BY LINE_NO

mapper.update:
/*
     SQL ID : MsgPushDAO.updatePushRcvrDelyn
     설  명 : 푸시 수신자 삭제
 */
UPDATE TB_LMS_MSG_MBL_SNDNG
SET RCVR_DELYN = 'Y'
WHERE MSG_MBL_SNDNG_ID = #{msgMblSndngId}
  AND RCVR_ID = #{rcvrId}

mapper.select:
/* SQL ID : MsgPushDAO.selectPushSndngList 설 명 : 푸시 발신 목록 조회 */
SELECT MSG.MSG_ID , MSG.TTL , NVL(SS.SNDNG_DTTM, MSG.RSRV_SNDNG_SDTTM) AS EFCTV_SNDNG_DTTM , (SELECT COUNT(*) FROM TB_LMS_MSG_RCV_TRGTR T WHERE T.MSG_ID = MSG.MSG_ID) AS RCVR_CNT , NVL(SS.SNDNG_YN, 'N') AS SNDNG_YN , CASE WHEN MSG.RSRV_SNDNG_SDTTM IS NOT NULL AND MSG.RSRV_SNDNG_CNCL_DTTM IS NULL AND NVL(SS.RSRV_CNT, 0) > 0 THEN 'Y' ELSE 'N' END AS RSRV_YN , NVL(SS.SNDNG_CNT, 0) AS SNDNG_SUCC_CNT , MSG.RSRV_SNDNG_CNCL_DTTM , MSG.DGRS_YR AS SBJCT_YR , SC.SMSTR_CHRTNM AS SBJCT_SMSTR , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , ORG.ORGNM , (SELECT S2.SNDNGNM FROM TB_LMS_MSG_MBL_SNDNG S2 WHERE S2.MSG_ID = MSG.MSG_ID AND S2.MBL_SNDNG_TYCD = #{mblSndngTycd} AND ROWNUM = 1) AS SNDNGNM , ROW_NUMBER() OVER (ORDER BY NVL(SS.SNDNG_DTTM, MSG.RSRV_SNDNG_SDTTM) DESC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT FROM TB_LMS_MSG MSG LEFT JOIN ( SELECT MSG_ID , MIN(CASE WHEN NVL(SNDNG_STSCD, CASE WHEN SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) <> 'RSRV' THEN SNDNG_DTTM END) AS SNDNG_DTTM , COUNT(CASE WHEN NVL(SNDNG_STSCD, CASE WHEN SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) = 'SCS' THEN 1 END) AS SNDNG_CNT , COUNT(CASE WHEN NVL(SNDNG_STSCD, CASE WHEN SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) = 'RSRV' THEN 1 END) AS RSRV_CNT , MAX(SNDNGYN) AS SNDNG_YN FROM TB_LMS_MSG_MBL_SNDNG WHERE SNDNGR_DELYN = 'N' AND MBL_SNDNG_TYCD = #{mblSndngTycd} GROUP BY MSG_ID ) SS ON MSG.MSG_ID = SS.MSG_ID LEFT JOIN TB_LMS_SBJCT SBJCT ON MSG.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SC ON SBJCT.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON SC.ORG_ID = ORG.ORG_ID WHERE MSG.RGTR_ID = #{sndngrId} AND MSG.MSG_TYCD = #{mblSndngTycd} AND (SS.MSG_ID IS NOT NULL OR MSG.RSRV_SNDNG_SDTTM IS NOT NULL)
ORDER BY LINE_NO

/* SQL ID : MsgPushDAO.selectPushSndngRcvrList 설 명 : 푸시 발신 수신자 목록 조회 */
SELECT S.MSG_MBL_SNDNG_ID , S.RCVR_ID , U.USERNM AS RCVRNM , T.READ_DTTM , T.READ_YN , U.STDNT_NO , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = S.RCVR_ID AND UC.CNTCT_TYCD = 'MBL_PHN') AS MBL_PHN , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = S.RCVR_ID AND UC.CNTCT_TYCD = 'INDV_EML') AS EML , S.SNDNGYN AS SNDNG_YN , S.SNDNG_STSCD , S.SNDNG_RSLT_CTS , ROW_NUMBER() OVER (ORDER BY U.USERNM ASC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT FROM TB_LMS_MSG_MBL_SNDNG S LEFT JOIN TB_LMS_USER U ON S.RCVR_ID = U.USER_ID LEFT JOIN TB_LMS_MSG_RCV_TRGTR T ON S.MSG_ID = T.MSG_ID AND S.RCVR_ID = T.USER_ID WHERE S.MSG_ID = #{msgId} AND S.MBL_SNDNG_TYCD = #{mblSndngTycd}
AND EXISTS (SELECT 1 FROM TB_LMS_MSG M WHERE M.MSG_ID = S.MSG_ID AND M.RGTR_ID = #{sndngrId})
ORDER BY LINE_NO

