/*
     SQL ID : MsgPushDAO.updatePushSndngrDelyn
     설  명 : 푸시 발신자 삭제
 */
UPDATE TB_LMS_MSG_MBL_SNDNG
SET SNDNGR_DELYN = 'Y'
WHERE MSG_ID = #{msgId}
  AND MBL_SNDNG_TYCD = #{mblSndngTycd}
  AND SNDNGR_ID = #{sndngrId}

mapper.insert:
/*
     SQL ID : MsgPushDAO.insertMsg
     설  명 : 메시지 등록
 */
INSERT INTO TB_LMS_MSG (
                         MSG_ID
                       , MSG_TMPLT_ID
                       , MSG_TYCD
                       , MSG_CTS_GBNCD
                       , SBJCT_ID
                       , DGRS_YR
                       , SMSTR
                       , TTL
                       , TXT_CTS
                       , HTML_CTS
                       , RSRV_SNDNG_SDTTM
                       , RGTR_ID
                       , REG_DTTM
) VALUES (
           #{msgId}
         , #{msgTmpltId}
         , #{msgTycd}
         , 'INDV_MSG'
         , #{sbjctId}
         , #{dgrsYr}
         , #{smstr}
         , #{ttl}
         , #{txtCts}
         , #{htmlCts}
         , #{rsrvSndngSdttm}
         , #{rgtrId}
         , FN_DTTM()
         )

/*
     SQL ID : MsgPushDAO.insertRcvTrgtr
     설  명 : 수신 대상자 등록
 */
INSERT INTO TB_LMS_MSG_RCV_TRGTR (
                                   MSG_ID
                                 , USER_ID
                                 , RCVRNM
                                 , RGTR_ID
                                 , REG_DTTM
) VALUES (
           #{msgId}
         , #{rcvrId}
         , #{rcvrnm}
         , #{rgtrId}
         , FN_DTTM()
         )

/*
     SQL ID : MsgPushDAO.insertMblSndng
     설  명 : 푸시 발송 등록
 */
INSERT INTO TB_LMS_MSG_MBL_SNDNG (
                                   MSG_MBL_SNDNG_ID
                                 , MSG_ID
                                 , SNDNG_RETRY_SEQNO
                                 , MBL_SNDNG_TYCD
                                 , SNDNGNM
                                 , SNDNG_TTL
                                 , SNDNG_CTS
                                 , SNDNG_PHNNO
                                 , SNDNG_DTTM
                                 , SNDNGR_ID
                                 , SNDNGYN
                                 , SNDNG_STSCD
                                 , SNDNG_RSLT_CTS
                                 , RCVR_ID
                                 , SNDNGR_DELYN
                                 , RCVR_DELYN
                                 , RGTR_ID
                                 , REG_DTTM
) VALUES (
           #{msgMblSndngId}
         , #{msgId}
         , 0
         , #{mblSndngTycd}
         , CASE WHEN #{sndngnm} IS NOT NULL THEN #{sndngnm} ELSE (SELECT U.USERNM FROM TB_LMS_USER U WHERE U.USER_ID = #{sndngrId}) END
         , #{sndngTtl}
         , #{sndngCts}
         , NVL(REPLACE(NVL(#{sndngrPhnno}, (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = #{sndngrId} AND UC.CNTCT_TYCD = 'MBL_PHN')), '-', ''), '00000000000')
         , CASE WHEN #{sndngStscd} = 'RSRV' THEN NULL ELSE FN_DTTM() END
         , #{sndngrId}
         , #{sndngYn}
         , #{sndngStscd}
         , #{sndngRsltCts, jdbcType=CLOB}
         , #{rcvrId}
         , 'N'
         , 'N'
         , #{rgtrId}
         , FN_DTTM()
         )

mapper.update:
/*
     SQL ID : MsgPushDAO.updateMsg
     설  명 : 메시지 수정
 */
UPDATE TB_LMS_MSG
SET TTL = #{ttl}
  , TXT_CTS = #{txtCts}
  , HTML_CTS = #{htmlCts}
  , RSRV_SNDNG_SDTTM = #{rsrvSndngSdttm}
  , SBJCT_ID = #{sbjctId}
  , DGRS_YR = #{dgrsYr}
  , SMSTR = #{smstr}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE MSG_ID = #{msgId}
  AND EXISTS (
      SELECT 1 FROM TB_LMS_MSG_MBL_SNDNG S
      WHERE S.MSG_ID = #{msgId}
        AND S.MBL_SNDNG_TYCD = #{mblSndngTycd}
        AND NVL(S.SNDNG_STSCD, CASE WHEN S.SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) = 'RSRV'
  )
  AND NOT EXISTS (
      SELECT 1 FROM TB_LMS_MSG_MBL_SNDNG S2
      WHERE S2.MSG_ID = #{msgId}
        AND S2.MBL_SNDNG_TYCD = #{mblSndngTycd}
        AND NVL(S2.SNDNG_STSCD, CASE WHEN S2.SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) <> 'RSRV'
  )

    AND RGTR_ID = #{sndngrId}

mapper.delete:
/*
     SQL ID : MsgPushDAO.deleteMblSndng
     설  명 : 푸시 발송 삭제
 */
DELETE FROM TB_LMS_MSG_MBL_SNDNG
WHERE MSG_ID = #{msgId}
  AND MBL_SNDNG_TYCD = #{mblSndngTycd}
  AND NVL(SNDNG_STSCD, CASE WHEN SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) = 'RSRV'

    AND EXISTS (SELECT 1 FROM TB_LMS_MSG M WHERE M.MSG_ID = #{msgId} AND M.RGTR_ID = #{sndngrId})

mapper.update:
/*
     SQL ID : MsgPushDAO.updatePushSndngRsrvCncl
     설  명 : 예약 푸시 취소
 */
UPDATE TB_LMS_MSG_MBL_SNDNG
   SET SNDNG_STSCD = 'CNCL'
     , SNDNGYN = 'N'
     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE MSG_ID = #{msgId}
   AND MBL_SNDNG_TYCD = #{mblSndngTycd}
   AND NVL(SNDNG_STSCD, CASE WHEN SNDNGYN = 'Y' THEN 'SCS' ELSE 'RSRV' END) = 'RSRV'

    AND EXISTS (SELECT 1 FROM TB_LMS_MSG M WHERE M.MSG_ID = #{msgId} AND M.RGTR_ID = #{sndngrId})

/*
     SQL ID : MsgPushDAO.updateMsgRsrvCncl
     설  명 : 예약 발신 취소
 */
UPDATE TB_LMS_MSG
SET RSRV_SNDNG_CNCL_DTTM = FN_DTTM()
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE MSG_ID = #{msgId}
  AND RSRV_SNDNG_SDTTM IS NOT NULL
  AND RSRV_SNDNG_CNCL_DTTM IS NULL

    AND RGTR_ID = #{sndngrId}

mapper.select:
/* SQL ID : MsgPushDAO.selectMsgRcvTrgtrList 설 명 : 수신 대상자 목록 조회 */ SELECT T.USER_ID AS RCVR_ID , U.USERNM AS RCVRNM , U.STDNT_NO , U.USER_TYCD , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = U.USER_ID AND UC.CNTCT_TYCD = 'MBL_PHN') AS MBL_PHN , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = U.USER_ID AND UC.CNTCT_TYCD = 'INDV_EML') AS EML , S.SNDNGYN AS SNDNG_YN , S.SNDNG_STSCD , S.SNDNG_RSLT_CTS FROM TB_LMS_MSG_RCV_TRGTR T INNER JOIN TB_LMS_USER U ON T.USER_ID = U.USER_ID LEFT JOIN TB_LMS_MSG_MBL_SNDNG S ON S.MSG_ID = T.MSG_ID AND S.RCVR_ID = T.USER_ID AND S.MBL_SNDNG_TYCD = #{mblSndngTycd} WHERE T.MSG_ID = #{msgId}
AND EXISTS (SELECT 1 FROM TB_LMS_MSG M WHERE M.MSG_ID = T.MSG_ID AND M.RGTR_ID = #{sndngrId})
ORDER BY U.USERNM ASC
